/** Rebuild the saved engineering example from its generated M1/M2/BOX masks.
 * Usage: node examples/projects/tfln-10x8-recovery/rebuild.mjs <output-directory> [mask-input.json]
 * The optional input can be generated by build_masks.py; the default is the
 * checked-in mask snapshot. The saved project is used only as a parity oracle.
 */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { gunzipSync } from 'node:zlib';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../../..');
const [outputArg, inputArg, ...extra] = process.argv.slice(2);
assert.ok(outputArg && extra.length === 0, 'Supply an output directory and optional mask JSON');
const output = resolve(outputArg);
const load = (path) => import(pathToFileURL(resolve(root, path)).href);
await (await load('scripts/process-benchmarks.mjs')).loadGeometryKernel();
const modelApi = await load('site/model.js');
const { difference, intersection, rectMulti } = await load('site/vector-geometry.js');
const { validateProcessModel } = await load('site/project-schema.js');
const { readProjectFile } = await load('site/project-io.js');
const { serializeGDS, serializeOASIS } = await load('site/layout-export.js');
const { flattenGDS, parseGDS } = await load('site/gds.js');
const { parseOAS } = await load('site/oasis.js');

const readMaybeGzip = (path) => {
  const bytes = readFileSync(path);
  return path.endsWith('.gz') ? gunzipSync(bytes) : bytes;
};
const input = readMaybeGzip(inputArg ? resolve(inputArg) : join(here, 'mask_input.json.gz'));
const masks = JSON.parse(input).arrays;
assert.ok(masks && ['m1', 'm2', 'boxVoid'].every((name) => Array.isArray(masks[name])));
const referenceBytes = readMaybeGzip(join(here, 'TFLN_10x8_REBUILT_editable.wafercad.gz'));
assert.equal(
  createHash('sha256').update(referenceBytes).digest('hex'),
  '43b758303c226c00ab9b4909ef6cb93223cfc607edd888a6f58d4ac8d62481f9',
  'Reference project integrity',
);
const reference = JSON.parse(referenceBytes);

const round = (value) => Math.round(value * 1e4) / 1e4;
const range = (ring, axis) => {
  const values = ring.map((point) => point[axis]);
  return [Math.min(...values), Math.max(...values)];
};
// The reference uses one processed eight-device row, translated ten times.
// Use the first mask row, and reject polygons crossing its cell boundaries.
const rowCenter = -1620;
const rowGeometry = (polygons) =>
  polygons
    .filter((poly) => {
      const ys = poly.flatMap((ring) => ring.map((point) => point[1]));
      const min = Math.min(...ys),
        max = Math.max(...ys),
        mid = (min + max) / 2;
      if (mid < rowCenter - 180 || mid >= rowCenter + 180) return false;
      assert.ok(min >= rowCenter - 180 - 1e-7 && max <= rowCenter + 180 + 1e-7);
      return true;
    })
    .map((poly) => poly.map((ring) => ring.map(([x, y]) => [round(x), round(y - rowCenter)])));
const rowMasks = Object.fromEntries(
  Object.entries(masks).map(([name, polys]) => [name, rowGeometry(polys)]),
);
assert.deepEqual([rowMasks.m1.length, rowMasks.m2.length, rowMasks.boxVoid.length], [24, 48, 8]);

const row = modelApi.createModel({ shape: 'rect', width: 1160, height: 360, thickness: 10 });
modelApi.applyOperation(row, {
  type: 'add',
  growth: 'direct',
  face: 'front',
  name: 'SiO2 BOX',
  area: row.boundary,
  thickness: 2,
});
const ln = modelApi.applyOperation(row, {
  type: 'add',
  growth: 'direct',
  face: 'front',
  name: 'LiNbO3 (X-cut)',
  area: row.boundary,
  thickness: 0.3,
});
for (const [name, area, thickness] of [
  ['M1', rowMasks.m1, 0.22],
  ['M2', rowMasks.m2, 0.08],
]) {
  const result = modelApi.applyOperation(row, {
    type: 'etch',
    etchProfile: 'directional',
    face: 'front',
    etchTargetLayerIds: [ln.layerId],
    thickness,
    area,
  });
  assert.ok(result.changed, `${name} etch failed: ${result.error || 'no change'}`);
}

// Engineering BOX void, not an HF kinetics simulation. Split each native
// region into the intersection and remainder, then remove BOX only in the void.
const roundGeometry = (geom) =>
  geom.map((poly) => poly.map((ring) => ring.map((p) => p.map(round))));
const regions = [];
for (const region of row.regions) {
  const keep = difference(region.geom, rowMasks.boxVoid);
  const released = intersection(region.geom, rowMasks.boxVoid);
  if (keep.length) regions.push({ ...structuredClone(region), geom: roundGeometry(keep) });
  if (released.length) {
    regions.push({
      ...structuredClone(region),
      id: `${region.id}-released`,
      stack: region.stack.filter((layer) => layer.layerId !== 'layer-1'),
      geom: roundGeometry(released),
    });
  }
}
row.regions = regions;
row.nextRegionId = Math.max(row.nextRegionId, 100);
validateProcessModel(row);

// GDS/OAS boundaries cannot represent polygon holes directly. Cut only at
// hole bounding-box x coordinates, preserving the original mask area.
const name = 'TFLN_REBUILT_10X8';
const elements = [];
for (const [layer, key] of [
  [11, 'm1'],
  [12, 'm2'],
]) {
  for (const poly of masks[key]) {
    const pieces = [];
    if (poly.length === 1) pieces.push(poly);
    else {
      const [minX, maxX] = range(poly[0], 0),
        [minY, maxY] = range(poly[0], 1);
      const xs = [
        ...new Set([minX, maxX, ...poly.slice(1).flatMap((hole) => range(hole, 0))]),
      ].sort((a, b) => a - b);
      for (let i = 1; i < xs.length; i++) {
        const left = xs[i - 1],
          right = xs[i];
        if (right - left < 1e-9) continue;
        const clip = rectMulti(
          right - left,
          maxY - minY + 1,
          (left + right) / 2,
          (minY + maxY) / 2,
        );
        for (const piece of intersection([poly], clip)) {
          assert.equal(piece.length, 1, 'Mask slice still has a hole');
          pieces.push(piece);
        }
      }
    }
    for (const piece of pieces) {
      const points = piece[0].map((point) => point.map(round));
      if (JSON.stringify(points[0]) === JSON.stringify(points.at(-1))) points.pop();
      if (points.length >= 3)
        elements.push({ kind: 'polygon', sourceCell: name, layer, datatype: 0, points });
    }
  }
}
assert.deepEqual(
  [elements.filter((e) => e.layer === 11).length, elements.filter((e) => e.layer === 12).length],
  [640, 480],
);

const arrayModel = {
  ...structuredClone(row),
  kernel: 'vector-2.5d-array-v1',
  width: 1160,
  height: 3600,
  boundary: rectMulti(1160, 3600),
  regions: [],
  array: {
    version: 1,
    templates: [{ id: 'native-mask-processed-8-pixel-row', model: row }],
    instances: Array.from({ length: 10 }, (_, index) => ({
      id: `row-${index + 1}`,
      templateId: 'native-mask-processed-8-pixel-row',
      x: 0,
      y: (index - 4.5) * 360,
    })),
  },
};
const layout = {
  root: name,
  elements,
  linework: [],
  bounds: { minX: -580, minY: -1800, maxX: 580, maxY: 1800, width: 1160, height: 3600 },
  combos: [11, 12].map((layer) => ({
    key: `${name}|${layer}|0`,
    cell: name,
    layer,
    datatype: 0,
    count: elements.filter((e) => e.layer === layer).length,
  })),
  units: {
    xy: 'µm',
    userUnitsPerDbu: 0.0001,
    metersPerDbu: 1e-10,
    dbuToMicron: 0.0001,
    hasPhysicalUnits: true,
  },
  warnings: [],
  name: 'TFLN S1 engineering 10x8 native M1 and M2, not authors original GDS',
  hierarchy: {},
};
const project = {
  format: 'WaferCAD-vector',
  version: 14,
  model: arrayModel,
  layout,
  selectedLayerKeys: ['11|0', '12|0'],
  activeCell: name,
  maskTransform: { x: 0, y: 0, scale: 1, rotation: 0 },
  activeFace: 'front',
  roi: null,
  roiAnchor: null,
  section: { a: [-550, 0], b: [550, 0] },
  planViews: { main: { zoom: 1, panX: 0, panY: 0 }, mask: { zoom: 1, panX: 0, panY: 0 } },
  display: {
    xyUnit: 'um',
    structurePalette: 'balanced',
    customStructurePalette: null,
    threeOpacity: 1,
    threeShowBorders: true,
    sectionShowBorders: false,
  },
  name: 'TFLN 10x8 newly mask-driven, native row process, ENGINEERING BOX',
  maskSourceMode: 'file',
  drawMask: { nextShapeId: 1, shapes: [] },
  maskRoi: null,
  maskRoiAnchor: 'center',
};

// Compare on the exact 0.1 nm grid. Remove only repeated points and integer-
// collinear intermediate vertices: those do not change polygon geometry.
function ringSignature(points) {
  let ring = points.map(([x, y]) => [Math.round(x * 1e4), Math.round(y * 1e4)]);
  if (ring.length > 1 && ring[0][0] === ring.at(-1)[0] && ring[0][1] === ring.at(-1)[1]) ring.pop();
  ring = ring.filter((p, i) => i === 0 || p[0] !== ring[i - 1][0] || p[1] !== ring[i - 1][1]);
  let changed = true;
  while (changed && ring.length > 3) {
    changed = false;
    ring = ring.filter((p, i) => {
      const a = ring[(i + ring.length - 1) % ring.length],
        b = ring[(i + 1) % ring.length];
      const cross = (p[0] - a[0]) * (b[1] - p[1]) - (p[1] - a[1]) * (b[0] - p[0]);
      const dot = (p[0] - a[0]) * (b[0] - p[0]) + (p[1] - a[1]) * (b[1] - p[1]);
      if (cross === 0 && dot >= 0) {
        changed = true;
        return false;
      }
      return true;
    });
  }
  assert.ok(ring.length >= 3, 'Degenerate polygon');
  const canonical = (vertices) => {
    let first = 0;
    for (let i = 1; i < vertices.length; i++) {
      if (
        vertices[i][0] < vertices[first][0] ||
        (vertices[i][0] === vertices[first][0] && vertices[i][1] < vertices[first][1])
      )
        first = i;
    }
    return JSON.stringify([...vertices.slice(first), ...vertices.slice(0, first)]);
  };
  return [canonical(ring), canonical([...ring].reverse())].sort()[0];
}
const geometrySignature = (geometry) =>
  geometry
    .map((poly) => [ringSignature(poly[0]), ...poly.slice(1).map(ringSignature).sort()].join('|'))
    .sort();
const layoutSignature = (items) =>
  items
    .map((element) => `${element.layer}|${element.datatype}|${ringSignature(element.points)}`)
    .sort();
const originalRow = reference.model.array.templates[0].model;
assert.deepEqual(arrayModel.array.instances, reference.model.array.instances, 'Array placements');
assert.deepEqual(row.layers, originalRow.layers, 'Material layers');
assert.equal(row.regions.length, originalRow.regions.length, 'Material region count');
for (const region of row.regions) {
  const expected = originalRow.regions.find((candidate) => candidate.id === region.id);
  assert.ok(expected, `Reference region ${region.id}`);
  assert.deepEqual(region.stack, expected.stack, `Material stack ${region.id}`);
  assert.deepEqual(
    geometrySignature(region.geom),
    geometrySignature(expected.geom),
    `Region geometry ${region.id}`,
  );
}
assert.deepEqual(
  layoutSignature(elements),
  layoutSignature(reference.layout.elements),
  'Mask layout parity',
);
const projectText = JSON.stringify(project);
await readProjectFile({ size: Buffer.byteLength(projectText), text: async () => projectText });

const gds = serializeGDS(elements, { cellName: name });
const oas = serializeOASIS(elements, { cellName: name });
const buffer = (bytes) => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
for (const [label, parsed] of [
  ['GDS', parseGDS(buffer(gds))],
  ['OAS', await parseOAS(buffer(oas))],
]) {
  const result = flattenGDS(parsed, name);
  assert.deepEqual(result.warnings || [], [], `${label} import warnings`);
  assert.deepEqual(
    layoutSignature(result.elements),
    layoutSignature(elements),
    `${label} round-trip geometry`,
  );
}
mkdirSync(output, { recursive: true });
writeFileSync(join(output, 'TFLN_10x8_REBUILT_editable.wafercad'), projectText);
writeFileSync(join(output, 'TFLN_M1_M2_10x8.gds'), gds);
writeFileSync(join(output, 'TFLN_M1_M2_10x8.oas'), oas);
console.log(
  JSON.stringify(
    {
      status: 'passed',
      maskInputSha256: createHash('sha256').update(input).digest('hex'),
      sites: 80,
      materialRegions: row.regions.length,
      maskPolygons: elements.length,
      coordinateGridNm: 0.1,
      projectRead: true,
      materialAndLayoutParity: true,
      gdsRoundTrip: true,
      oasisRoundTrip: true,
      caveat:
        'The BOX void and mask layout are an engineering reconstruction, not the authors’ original masks or an HF simulation.',
      output,
    },
    null,
    2,
  ),
);
